mapper.update:
UPDATE article
SET status = #{status},
    published_at = #{publishedAt},
    update_time = #{updateTime}
WHERE id = #{id}

mapper.select:
SELECT 
FROM article

    AND status = #{status}
    AND category_id = #{categoryId}
    AND title LIKE CONCAT(#{keyword}, '%')

ORDER BY id DESC

    LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM article

    AND status = #{status}
    AND category_id = #{categoryId}
    AND title LIKE CONCAT(#{keyword}, '%')

SELECT 
FROM article
WHERE status = 1
AND category_id = #{categoryId}
ORDER BY published_at DESC, id DESC

    LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM article
WHERE status = 1
AND category_id = #{categoryId}

SELECT 
FROM article
WHERE status = 1 AND artist_id = #{artistId}
ORDER BY published_at DESC, id DESC

    LIMIT #{size} OFFSET #{offset}
